<div class="page-heading"><div><p class="eyebrow"><?= $role === 'family' ? 'FAMILY CARE' : ($role === 'admin' ? 'PILOT COORDINATION' : 'YOUR ASSIGNMENTS') ?></p><h1><?= $role === 'caretaker' ? 'Assigned jobs.' : 'Care requests.' ?></h1><p class="page-lead"><?= $role === 'family' ? 'Follow the progress of care requested for your family graves.' : ($role === 'admin' ? 'Assign eligible caretakers and keep the pilot moving.' : 'Review each assignment, confirm the grave, and keep the family informed.') ?></p></div><?php if ($role === 'family'): ?><a class="btn btn-primary btn-sm" href="?page=graves">Choose a grave <?= icon('arrow', 'size-4') ?></a><?php endif; ?></div>
<?php if (!$requests): ?><section class="surface-card grave-empty"><div class="next-illustration" aria-hidden="true"><?= icon('document', 'size-10') ?></div><h2><?= $role === 'caretaker' ? 'No jobs assigned yet' : 'No care requests yet' ?></h2><p><?= $role === 'family' ? 'Open a registered grave to request an available service.' : ($role === 'admin' ? 'Requests from families will appear here for assignment.' : 'An administrator will assign a request after verifying you and granting cemetery access.') ?></p><?php if ($role === 'family'): ?><a class="btn btn-primary" href="?page=graves">View my graves <?= icon('arrow', 'size-4') ?></a><?php endif; ?></section><?php else: ?><div class="request-card-grid"><?php foreach ($requests as $item): ?><article class="surface-card request-card"><div class="request-card-top"><span class="eyebrow">REQUEST #<?= (int) $item['id'] ?></span><?= status_badge(request_status_label($item['status']), request_status_tone($item['status'])) ?></div><h2><?= e($item['service_name']) ?></h2><p class="request-card-person"><?= e($item['deceased_name']) ?> · <?= e($item['cemetery_name']) ?></p><dl class="request-card-meta"><div><dt>Preferred</dt><dd><?= e(date('M j, Y', strtotime($item['preferred_date']))) ?></dd></div><div><dt>Saved price</dt><dd><?= e(catalog_money((int) $item['price_centavos'])) ?></dd></div><?php if ($role === 'admin'): ?><div><dt>Family</dt><dd><?= e($item['family_name']) ?></dd></div><?php endif; ?><?php if ($item['caretaker_name']): ?><div><dt>Caretaker</dt><dd><?= e($item['caretaker_name']) ?></dd></div><?php endif; ?></dl><a class="small-link" href="?page=request&amp;id=<?= (int) $item['id'] ?>">Open request <?= icon('arrow', 'size-4') ?></a></article><?php endforeach; ?></div><?php endif; ?>
